/**
 * Replaces all segments with those from an explicit commit, while keeping generation, version and
 * counter so future commits remain write once.
 */
void replace(IndexCommit commit, Directory directory, LiveIndexWriterConfig config)
    throws IOException {
  final Directory commitDirectory = commit.getDirectory();
  final String segmentsFileName = commit.getSegmentsFileName();
  final long commitGeneration = commit.getGeneration();
  final int commitSegmentCount = commit.getSegmentCount();
  final Collection<String> commitFiles = commit.getFileNames();

  if (commitDirectory != directory) {
    throw new IllegalArgumentException(
        "IndexCommit's directory doesn't match my directory, expected="
            + directory
            + ", got="
            + commitDirectory);
  }

  final SegmentInfos other = readCommit(directory, segmentsFileName);
  replace(other);
  lastGeneration = commitGeneration;
  final int loadedSegments = this.segments.size();

  final InfoStream infoStream = config.getInfoStream();
  if (infoStream.isEnabled("IW")) {
    infoStream.message(
        "IW",
        "init: loaded commit \""
            + segmentsFileName
            + "\" generation="
            + commitGeneration
            + " segmentCount="
            + commitSegmentCount
            + " files="
            + commitFiles.size()
            + " loaded="
            + loadedSegments);
  }
}

/**
 * Replaces all segments in this instance, but keeps generation, version, counter so that future
 * commits remain write once.
 */
void replace(SegmentInfos other) {
  rollbackSegmentInfos(other.asList());
  lastGeneration = other.lastGeneration;
}

/** Returns sum of all segment's maxDocs. Note that this does not include deletions */
public int totalMaxDoc() {
  long count = 0;
  for (SegmentCommitInfo info : this) {
    count += info.info.maxDoc();
  }
  // we should never hit this, checks should happen elsewhere...
  assert count <= IndexWriter.getActualMaxDocs();
  return Math.toIntExact(count);
}

/** Call this before committing if changes have been made to the segments. */
public void changed() {
  version++;
  // System.out.println(Thread.currentThread().getName() + ": SIS.change to version=" + version);
  // new Throwable().printStackTrace(System.out);
}

void setVersion(long newVersion) {
  if (newVersion < version) {
    throw new IllegalArgumentException(
        "newVersion (="
            + newVersion
            + ") cannot be less than current version (="
            + version
            + ")");
  }
  // System.out.println(Thread.currentThread().getName() + ": SIS.setVersion change from " +
  // version + " to " + newVersion);
  version = newVersion;
}

